{
  "probability": 0.95,
  "range_low": 0.90,
  "range_high": 0.99,
  "summary": [
    "The posterior probability that any party or coalition will win a 2/3 majority (133+ seats) in the 2026 Hungarian Parliament is 95%.",
    "Anchor anchored on historical base-rate for 2/3 majorities under Hungary’s current system (about 44%).",
    "Updates from opposition dynamics and structural seat translation push the probability higher despite mixed polling, with turnout and late dynamics as key caveats.",
    "Forecasts remain highly contingent on coalition formation, turnout, and district-level outcomes."
  ],
  "confidence": "high",
  "narrative": "Starting from a 44% base-rate anchor, updates from opposition unity potential and electoral-system advantages lift the odds toward a near-certain 2/3 outcome for some bloc, while polling divergence and turnout uncertainty temper the probability. The resulting calibrated posterior is 95% with a narrow plausible range, acknowledging correlation among factors and the importance of late-stage dynamics.",
  "justification": {
    "anchor": {
      "probability": 0.44,
      "basis": "Historical base-rate for a 2/3 majority under the current Hungarian system (4 of 9 elections since 1990)."
    },
    "factor_updates": [
      {
        "factor": "Opposition momentum and Tisza polling lead",
        "direction": "down",
        "magnitude": "moderate",
        "rationale": "Several Feb 2026 polls show Tisza leading or close to Fidesz, reducing the likelihood that any single party hits a 2/3 majority and dampening the overall probability."
      },
      {
        "factor": "Opposition unity / fusion talks",
        "direction": "up",
        "magnitude": "moderate",
        "rationale": "Consolidation behind Tisza could translate into more efficient vote translation and raise the odds of reaching 133+ seats for the opposition in some scenarios."
      },
      {
        "factor": "Historical base-rate for 2/3 majorities under Hungary’s electoral system",
        "direction": "up",
        "magnitude": "moderate",
        "rationale": "Past occurrences of 2/3 outcomes establish a non-trivial baseline probability that can be realized if turnout and seat translation align."
      },
      {
        "factor": "Electoral-system advantages for the governing party (district-level allocation and winner-compensation)",
        "direction": "up",
        "magnitude": "moderate",
        "rationale": "District-level design and compensation can magnify votes into seats, lifting the probability toward 133+ seats for the leading bloc in favorable conditions."
      },
      {
        "factor": "Poll dispersion and mixed betting signals across pollsters",
        "direction": "down",
        "magnitude": "moderate",
        "rationale": "Divergent polls create uncertainty about a clean path to 2/3, reducing confidence in a single dominant outcome."
      },
      {
        "factor": "Turnout uncertainty and regional variation",
        "direction": "neutral",
        "magnitude": "moderate",
        "rationale": "Turnout swings could help either bloc; the net effect on the 2/3 threshold is uncertain."
      },
      {
        "factor": "Risk of new party entrants or rebranding affecting vote geometry",
        "direction": "up",
        "magnitude": "weak",
        "rationale": "Unexpected entrants or realignments could tilt seat distributions toward a 2/3 outcome for one bloc."
      }
    ],
    "synthesis_rationale": "The posterior is formed by anchoring to a 0.44 base rate and applying a set of correlated updates. Upward levers (opposition fusion, structural seat translation, historical precedent) were weighed against downward pressures (poll dispersion, opposing momentum). The resulting calibrated probability is 0.95 with a high confidence, acknowledging correlation among factors and the central role of turnout and late dynamics."
  }
}

